Save Last Sync Timestamp.code:
// Remember when this sync ran so the next run can pick up from here.
set(
  // 1) Key.
  'sync:dhis2:lastRun',
  // 2) String value.
  new Date().toISOString()
);

Store Patient Hash.code:
// Cache a patient's key fields as a Redis hash.
hset(
  // 1) Key, namespaced by record type and id.
  `patient:${$.data.patientId}`,
  // 2) Field/value pairs.
  {
    name: $.data.name,
    facility: $.data.facilityCode,
    ihs_number: $.data.ihsNumber,
  }
);

Store JSON Document.code:
// Save a full JSON document under one key (requires RedisJSON).
jSet(
  // 1) Key.
  `beneficiary:${$.data.beneficiaryId}`,
  // 2) Object to store at the root path.
  {
    name: $.data.name,
    household: $.data.householdId,
    enrolledOn: $.data.enrolledOn,
    status: 'active',
  }
);

Store Many JSON Documents.code:
// Save a batch of records as JSON documents in one call.
mSet(
  $.data.records.map(record => ({
    key: `facility:${record.code}`,
    value: record, // object or string
  }))
);

Get Hash Field.code:
// Read one field from a patient hash.
hget(
  // 1) Key.
  `patient:${$.data.patientId}`,
  // 2) Field name.
  'ihs_number'
);

Get Many JSON Documents.code:
// Read several JSON documents in one call.
mGet(
  $.data.facilityCodes.map(code => `facility:${code}`)
);

Scan Keys By Pattern.code:
// Find all cached patient hashes; state.data becomes an array of keys.
scan('patient:*', {
  type: 'hash', // 'string' | 'hash' | 'json' ...
  count: 500, // keys fetched per scan iteration
});
